const paginas  = $('Leer Paginas').all().map(i => i.json);
const anuncios = $input.all().map(i => i.json);
const si = (v) => String(v == null ? '' : v).trim().toUpperCase() === 'SI';

const activas = paginas.filter(p => si(p.activo));
const act = anuncios.filter(a => si(a.activo));
const listos = act.filter(a => activas.some(p => String(p.page_id).trim() === String(a.page_id).trim())
  && String(a.producto_id || '').trim() && String(a.wa_destino || '').trim() && String(a.story_id || '').trim());

const destinos = {};
for (const a of act) { const d = String(a.wa_destino || '(vacio)').trim() || '(vacio)'; destinos[d] = (destinos[d] || 0) + 1; }

const problemas = [];
for (const a of act) {
  const enPaginaActiva = activas.some(p => String(p.page_id).trim() === String(a.page_id).trim());
  if (!enPaginaActiva) { problemas.push(a.ad_id + ' — activo pero su pagina NO lo esta'); continue; }
  if (!String(a.producto_id || '').trim()) problemas.push(a.ad_id + ' — sin producto_id');
  if (!String(a.wa_destino || '').trim())  problemas.push(a.ad_id + ' — sin wa_destino');
  if (!String(a.story_id   || '').trim())  problemas.push(a.ad_id + ' — sin story_id');
}

return [{ json: {
  leido_en: new Date().toISOString(),
  FB_Paginas: paginas.map(p => ({ page_id: p.page_id, nombre: p.nombre, activo: p.activo })),
  paginas_activas: activas.map(p => p.nombre + ' (' + p.page_id + ')'),
  anuncios_totales: anuncios.length,
  anuncios_activo_si: act.length,
  anuncios_listos_para_contestar: listos.length,
  destinos_wa: destinos,
  problemas,
  detalle_listos: listos.map(a => ({ ad_id: a.ad_id, page_id: a.page_id, producto_id: a.producto_id, wa_destino: a.wa_destino, story_id: a.story_id })),
} }];
